import os
import sys
from html.parser import HTMLParser

VOID_TAGS = {'meta', 'link', 'br', 'img', 'input', 'hr', 'source', 'path', 'rect', 'circle'}


class TagBalanceChecker(HTMLParser):
    def __init__(self):
        super().__init__()
        self.open_tags = []
        self.mismatches = []

    def handle_starttag(self, tag, attrs):
        if tag not in VOID_TAGS:
            self.open_tags.append((tag, self.getpos()))

    def handle_endtag(self, tag):
        if tag in VOID_TAGS:
            return
        if not self.open_tags or self.open_tags[-1][0] != tag:
            self.mismatches.append((tag, self.getpos(), self.open_tags[-1] if self.open_tags else None))
            return
        self.open_tags.pop()


project_folder = sys.argv[1]
for artboard in sys.argv[2:]:
    checker = TagBalanceChecker()
    with open(os.path.join(project_folder, artboard), encoding='utf-8') as artboard_file:
        checker.feed(artboard_file.read())
    print(artboard, 'mismatches', checker.mismatches[:3], 'unclosed', checker.open_tags[:3])
